SELECT * FROM (SELECT e.event_id,'D:'||s.dispatch_id case_id,e.activity,e.timestamp FROM (SELECT 'D:'||dispatch_id||':requested' event_id,'Dispatch Requested' activity,requested_at timestamp,dispatch_id source_key FROM dispatch_order WHERE requested_at IS NOT NULL AND (1=1)) e JOIN dispatch_order s ON s.dispatch_id=e.source_key WHERE s.dispatch_id IS NOT NULL UNION ALL SELECT e.event_id,'D:'||s.dispatch_id case_id,e.activity,e.timestamp FROM (SELECT 'D:'||dispatch_id||':approved' event_id,'Dispatch Approved' activity,approved_at timestamp,dispatch_id source_key FROM dispatch_order WHERE approved_at IS NOT NULL AND (1=1)) e JOIN dispatch_order s ON s.dispatch_id=e.source_key WHERE s.dispatch_id IS NOT NULL UNION ALL SELECT e.event_id,'D:'||s.dispatch_id case_id,e.activity,e.timestamp FROM (SELECT 'M:'||movement_id event_id,'Goods Dispatched' activity,occurred_at timestamp,movement_id source_key FROM goods_movement WHERE occurred_at IS NOT NULL AND (movement_code='OUT')) e JOIN goods_movement s ON s.movement_id=e.source_key WHERE s.dispatch_id IS NOT NULL UNION ALL SELECT e.event_id,'D:'||s.dispatch_id case_id,e.activity,e.timestamp FROM (SELECT 'T:'||task_id||':start' event_id,'Picking Started' activity,started_at timestamp,task_id source_key FROM warehouse_task_history WHERE started_at IS NOT NULL AND (task_code='PICK')) e JOIN warehouse_task_history s ON s.task_id=e.source_key WHERE s.dispatch_id IS NOT NULL UNION ALL SELECT e.event_id,'D:'||s.dispatch_id case_id,e.activity,e.timestamp FROM (SELECT 'T:'||task_id||':complete' event_id,'Picking Completed' activity,completed_at timestamp,task_id source_key FROM warehouse_task_history WHERE completed_at IS NOT NULL AND (task_code='PICK')) e JOIN warehouse_task_history s ON s.task_id=e.source_key WHERE s.dispatch_id IS NOT NULL UNION ALL SELECT e.event_id,'D:'||s.dispatch_id case_id,e.activity,e.timestamp FROM (SELECT 'T:'||task_id||':start' event_id,'Packing Started' activity,started_at timestamp,task_id source_key FROM warehouse_task_history WHERE started_at IS NOT NULL AND (task_code='PACK')) e JOIN warehouse_task_history s ON s.task_id=e.source_key WHERE s.dispatch_id IS NOT NULL UNION ALL SELECT e.event_id,'D:'||s.dispatch_id case_id,e.activity,e.timestamp FROM (SELECT 'T:'||task_id||':complete' event_id,'Packing Completed' activity,completed_at timestamp,task_id source_key FROM warehouse_task_history WHERE completed_at IS NOT NULL AND (task_code='PACK')) e JOIN warehouse_task_history s ON s.task_id=e.source_key WHERE s.dispatch_id IS NOT NULL UNION ALL SELECT e.event_id,'D:'||s.dispatch_id case_id,e.activity,e.timestamp FROM (SELECT 'H:'||handling_id||':start' event_id,'Loading Started' activity,started_at timestamp,handling_id source_key FROM handling_history WHERE started_at IS NOT NULL AND (handling_code='LOAD')) e JOIN handling_history s ON s.handling_id=e.source_key WHERE s.dispatch_id IS NOT NULL UNION ALL SELECT e.event_id,'D:'||s.dispatch_id case_id,e.activity,e.timestamp FROM (SELECT 'H:'||handling_id||':complete' event_id,'Loading Completed' activity,completed_at timestamp,handling_id source_key FROM handling_history WHERE completed_at IS NOT NULL AND (handling_code='LOAD')) e JOIN handling_history s ON s.handling_id=e.source_key WHERE s.dispatch_id IS NOT NULL) ORDER BY case_id,timestamp,event_id;
